package dev.danielc.fujiapp;
import android.graphics.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class LightFrameTest {
 @Test public void backgroundComesFromPhotoAndOriginalStaysIntact(){for(int style=8;style<=10;style++){Bitmap source=Bitmap.createBitmap(600,400,Bitmap.Config.ARGB_8888);source.eraseColor(Color.CYAN);PhotoFrame.Options o=new PhotoFrame.Options();o.style=style;Bitmap result=PhotoFrame.render(source,new PhotoDetails(),o);int corner=result.getPixel(0,0);assertTrue(Color.green(corner)>Color.red(corner));assertTrue(Color.blue(corner)>Color.red(corner));assertEquals(Color.CYAN,source.getPixel(0,0));assertFalse(source.isRecycled());assertTrue(result.getWidth()>source.getWidth());assertTrue(result.getHeight()>source.getHeight());result.recycle();source.recycle();}}
 @Test public void portraitAndLandscapePreviewsMatchExportGeometry(){for(boolean portrait:new boolean[]{false,true}){Bitmap preview=Bitmap.createBitmap(portrait?400:600,portrait?600:400,Bitmap.Config.ARGB_8888),full=Bitmap.createBitmap(portrait?800:1200,portrait?1200:800,Bitmap.Config.ARGB_8888);for(int style=8;style<=10;style++){PhotoFrame.Options o=new PhotoFrame.Options();o.style=style;Bitmap a=PhotoFrame.render(preview,new PhotoDetails(),o),b=PhotoFrame.render(full,new PhotoDetails(),o);assertEquals((double)a.getWidth()/a.getHeight(),(double)b.getWidth()/b.getHeight(),.005);a.recycle();b.recycle();}preview.recycle();full.recycle();}}
 @Test public void sidebarCanMoveWithoutCroppingOrChangingCanvas(){Bitmap source=Bitmap.createBitmap(600,400,Bitmap.Config.ARGB_8888);source.eraseColor(Color.RED);PhotoFrame.Options o=new PhotoFrame.Options();o.style=9;o.parameters=false;Bitmap left=PhotoFrame.render(source,new PhotoDetails(),o);o.sidebarRight=true;Bitmap right=PhotoFrame.render(source,new PhotoDetails(),o);assertEquals(left.getWidth(),right.getWidth());assertEquals(left.getHeight(),right.getHeight());int x=right.getWidth()/4,y=right.getHeight()/2;assertEquals(Color.RED,right.getPixel(x,y));assertNotEquals(Color.RED,left.getPixel(x,y));assertEquals(Color.RED,source.getPixel(0,0));left.recycle();right.recycle();source.recycle();}
 @Test public void paletteSeesColorsAcrossEntirePhoto(){int[] colors={Color.RED,Color.BLUE,Color.GREEN,Color.YELLOW,Color.MAGENTA},pixels=new int[90*60];for(int y=0;y<60;y++)for(int x=0;x<90;x++)pixels[y*90+x]=colors[x/18];Bitmap source=Bitmap.createBitmap(pixels,90,60,Bitmap.Config.ARGB_8888);java.util.Set<Integer> actual=new java.util.HashSet<>();for(int color:PhotoPalette.colors(source))actual.add(color);assertEquals(5,actual.size());for(int color:colors)assertTrue(actual.contains(color));source.recycle();}
 @Test public void monochromePaletteDoesNotInventColors(){Bitmap source=Bitmap.createBitmap(32,32,Bitmap.Config.ARGB_8888);source.eraseColor(Color.CYAN);for(int color:PhotoPalette.colors(source))assertEquals(Color.CYAN,color);assertEquals(Color.CYAN,source.getPixel(0,0));source.recycle();}
 @Test public void exportSnapshotKeepsLightEffects(){PhotoFrame.Options o=new PhotoFrame.Options();o.blur=7;o.corners=30;o.shadow=24;o.sidebarRight=true;PhotoFrame.Options copy=o.copy();o.blur=1;o.corners=0;o.shadow=0;o.sidebarRight=false;assertEquals(7,copy.blur);assertEquals(30,copy.corners);assertEquals(24,copy.shadow);assertTrue(copy.sidebarRight);}
}
